async function fetchDbAnalytics(days = 30) {
  const sql = getDbClient();
  if (!sql) return { dailyRevenue: [], statusBreakdown: [], topProducts: [] };
  const dailyRevenue = [];
  const statusBreakdown = [];
  const topProducts = [];
  try {
    const daily = await sql.query(`
      SELECT 
        DATE(created_at) as day,
        COUNT(*) as orders,
        SUM(total_amount) as revenue
      FROM orders
      WHERE created_at >= NOW() - INTERVAL '${days} days'
      GROUP BY DATE(created_at)
      ORDER BY day ASC
    `).catch(() => []);
    (daily || []).forEach((r2) => dailyRevenue.push({
      day: r2.day,
      orders: Number(r2.orders || 0),
      revenue: Number(r2.revenue || 0)
    }));
  } catch (_) {
  }
  try {
    const breakdown = await sql.query(`
      SELECT status, COUNT(*) as cnt
      FROM orders
      GROUP BY status
      ORDER BY cnt DESC
    `).catch(() => []);
    (breakdown || []).forEach((r2) => statusBreakdown.push({ status: r2.status, count: Number(r2.cnt || 0) }));
  } catch (_) {
  }
  try {
    const top = await sql.query(`
      SELECT 
        oi.product_name as name,
        oi.product_id as product_id,
        SUM(oi.quantity) as total_qty,
        SUM(oi.quantity * oi.price) as total_revenue
      FROM order_items oi
      GROUP BY oi.product_name, oi.product_id
      ORDER BY total_qty DESC
      LIMIT 10
    `).catch(() => []);
    (top || []).forEach((r2) => topProducts.push({
      name: r2.name,
      productId: r2.product_id,
      totalQty: Number(r2.total_qty || 0),
      totalRevenue: Number(r2.total_revenue || 0)
    }));
  } catch (_) {
  }
  return { dailyRevenue, statusBreakdown, topProducts };
}
